import { Loader2 } from 'lucide-react';

/**
 * Slim startup progress bar shown under the header while the dashboard's
 * initial backend queries are still settling. Each step maps to one HTTP
 * call (GTFS feed -> route shapes -> summary -> transfer graph), so the bar
 * moves in real steps instead of pretending to be an indeterminate spinner.
 * Auto-hides when every step has completed.
 */

interface Props {
  done: number;
  total: number;
  label: string;
}

export default function LoadingBar({ done, total, label }: Props) {
  const pct = Math.min(100, Math.round((done / total) * 100));
  return (
    <div
      role="status"
      aria-live="polite"
      aria-label={`Startup progress: ${label}`}
      className="border-b border-border bg-card px-4 py-2"
    >
      <div className="flex items-center justify-between gap-3">
        <span className="flex items-center gap-1.5 text-[11px] text-text-muted">
          <Loader2 className="h-3.5 w-3.5 animate-spin text-optimized" />
          {label}…
        </span>
        <span className="text-[11px] font-semibold tabular-nums text-text-secondary">
          {pct}%
        </span>
      </div>
      <div className="mt-1.5 h-1 overflow-hidden rounded-full bg-border">
        <div
          className="h-full rounded-full bg-gradient-to-r from-optimized via-accent to-bottleneck transition-[width] duration-300 ease-out"
          style={{ width: `${pct}%` }}
        />
      </div>
    </div>
  );
}
