// ---- T158 (v1.1): five-shell registry -------------------------------------
//
// The 19-view flat surface (frozen as tag `v1.0`) collapsed into 5 shells;
// every former view is now a *section* inside one. The section KEY is the old
// view key — deliberate: MapWorkspace, AppHeader pickers, useMapLayers,
// useTravelPlanner and useStaticData all switch on those keys and are
// untouched by the fold. Only the URL layer and navigation changed shape.
//
// `data` makes each shell/section's evidentiary basis explicit — the trust
// story of the dashboard. It is audited against the backend routers:
//   measured = every number traces to GTFS-RT observations (service_quality,
//     measured, operations, coverage routers)
//   modeled = schedule/circuity simulation only, no observed input
//     (circuity, transfers/optimize routers)
//   mixed = computed from measured weights/actuals but the conclusions are
//     model output (brief reports measured lateness plus modeled proposals)
// Sections that make no data claims at all (diagnostics) omit the field.

export type View = 'home' | 'map' | 'plan' | 'measure' | 'trust';

export interface SectionDef {
  key: string;
  label: string;
  desc: string;
  Icon: typeof MapIcon;
  tip?: string;
  /** Explicit T158 fold decision: `true` = labelled experimental on purpose
   * (with wipNote saying why); absent = resolved clean, flag dropped. */
  wip?: boolean;
  wipNote?: string;
  data?: 'measured' | 'modeled' | 'mixed';
}

export interface ShellDef {
  key: View;
  label: string;
  desc: string;
  Icon: typeof MapIcon;
  data?: 'measured' | 'modeled' | 'mixed';
  tip?: string;
  /** Tabbed workspace (Map/Plan share MapWorkspace) vs stacked sections. */
  workspace: boolean;
  sections: SectionDef[];
  defaultSection?: string;
}

