/** Flat ordered section list (registry source of truth for the smoke test). */
export const ALL_SECTIONS: SectionDef[] = SHELLS.flatMap((s) => s.sections);

export function shellOf(sectionKey: string): ShellDef | null {
  return SHELLS.find((s) => s.sections.some((sec) => sec.key === sectionKey)) ?? null;
}

export function findSection(sectionKey: string): { shell: ShellDef; section: SectionDef } | null {
  for (const shell of SHELLS) {
    const section = shell.sections.find((sec) => sec.key === sectionKey);
    if (section) return { shell, section };
  }
  return null;
}

/** Sections in a shell the user can land on; falls back to the shell default. */
export function activeSectionFor(shell: View, sectionKey: string | null): string | null {
  if (shell === 'home') return null;
  const def = SHELLS.find((s) => s.key === shell);
  if (!def) return null;
  if (sectionKey && def.sections.some((s) => s.key === sectionKey)) return sectionKey;
  return def.defaultSection ?? def.sections[0]?.key ?? null;
}

