// ---- URL layer (T158): real paths, hash fallback ---------------------------
export const PERIOD_VALUES = new Set(['all_day', 'am_rush', 'midday', 'pm_rush', 'late_night']);

/** Vite base: '/' in dev/prod, '/miway-findings/demo/' on the Pages demo. */
const BASE_URL = (import.meta.env.BASE_URL ?? '/').replace(/\/$/, '');

export type RouteTarget = { section: string | null; route: string | null };

/** Build the canonical URL for a navigation target. Real path in prod
 * (`/measure/reliability?route=36`); under the Pages demo the same shape sits
 * under the demo base (`/miway-findings/demo/reliability`) — shareable
 * councillor-packet links either way. */
export function pathFor(target: RouteTarget): string {
  const seg = target.section ? `/${target.section}` : '/';
  const q = target.route ? `?route=${encodeURIComponent(target.route)}` : '';
  return `${BASE_URL}${seg}${q}`;
}

/** Legacy deep-link map: keys that no longer own a URL of their own redirect
 * to the section that now carries their content, plus an optional anchor.
 * Two generations live here: pre-T158 flat view keys (now sections of a
 * shell) and genuinely retired panels (changeover, equity — T158 rule 3). */
export const LEGACY_VIEW_MAP: Record<string, { section: string; anchor?: string }> = {
  // retired outright by T158
  changeover: { section: 'scoreboard' },
  equity: { section: 'brief', anchor: 'brief-equity' },
  // pre-T158 flat keys -> their new shell section
  explore: { section: 'explore' },
  optimize: { section: 'optimize' },
  routes: { section: 'routes' },
  trunkfeeder: { section: 'trunkfeeder' },
  travel: { section: 'travel' },
  servicequality: { section: 'servicequality' },
  reliability: { section: 'reliability' },
  tripcheck: { section: 'tripcheck' },
  earlydepartures: { section: 'earlydepartures' },
  measured: { section: 'measured' },
  slowness: { section: 'slowness' },
  coverage: { section: 'coverage' },
  scoreboard: { section: 'scoreboard' },
  peers: { section: 'peers' },
  brief: { section: 'brief' },
  diagnostics: { section: 'diagnostics' },
  // older consolidations, kept working
  ghosttrips: { section: 'servicequality', anchor: 'sq-ghosts' },
  trends: { section: 'servicequality', anchor: 'sq-trends' },
  routegaps: { section: 'trunkfeeder' },
};

/** Resolve any address token (path segment, old hash key, `?view=` value)
 * to a live section key, following LEGACY_VIEW_MAP. */
export function resolveSectionToken(token: string | undefined | null): { section: string | null; anchor?: string } {
  if (!token) return { section: null };
  if (findSection(token)) return { section: token };
  const legacy = LEGACY_VIEW_MAP[token];
  if (legacy) return { section: legacy.section, anchor: legacy.anchor };
  return { section: null };
}

/** Parse the current location into a navigation target. Handles all three
 * address shapes this app has ever used:
 *   1. real path  /measure/reliability?route=36   (T158, canonical)
 *   2. old hash   #reliability&route=36           (pre-T158)
 *   3. query link ?view=reliability               (pre-T35 shares)
 * Legacy keys are mapped; the caller rewrites the address bar to canonical. */
export function parseLocation(): { target: RouteTarget; anchor?: string } {
  const loc = window.location;

  // Hash shapes: legacy `#reliability&route=36` AND the demo's hash-carried
  // real path `#/miway-findings/demo/reliability?route=36` (the Pages demo
  // cannot serve /section paths, so the canonical URL rides after the #).
  if (loc.hash && loc.hash.length > 1) {
    const raw = loc.hash.replace(/^#/, '').trim();
    // An embedded `?query` belongs to the hash-carried path; split it off.
    const qIdx = raw.indexOf('?');
    const pathPart = qIdx === -1 ? raw : raw.slice(0, qIdx);
    const queryPart = qIdx === -1 ? '' : raw.slice(qIdx + 1);
    let viewKey: string | undefined;
    let route: string | null = null;
    const parseParam = (part: string) => {
      const eq = part.indexOf('=');
      const key = eq === -1 ? part : part.slice(0, eq);
      const value = eq === -1 ? '' : part.slice(eq + 1);
      try {
        if (key === 'route' && value) route = decodeURIComponent(value);
        else if (key === 'period' && value) {
          /* sticky global filter state — parsed for compat, kept out of URLs */
        } else if (key && !viewKey) viewKey = key;
      } catch {
        // malformed percent-encoding -> ignore the bad token
      }
    };
    pathPart.split('&').forEach(parseParam);
    if (queryPart) queryPart.split('&').filter(Boolean).forEach(parseParam);
    // Hash-carried path: strip the Vite base and take the first segment.
    if (viewKey && viewKey.startsWith('/')) {
      let p = viewKey;
      if (BASE_URL && p.startsWith(BASE_URL)) p = p.slice(BASE_URL.length) || '/';
      viewKey = p.split('/').filter(Boolean)[0] || undefined;    }
    const resolved = resolveSectionToken(viewKey);
    return { target: { section: resolved.section, route }, anchor: resolved.anchor };
  }

  // Real path under the Vite base.
  let p = loc.pathname;
  if (BASE_URL && p.startsWith(BASE_URL)) p = p.slice(BASE_URL.length) || '/';
  const seg = p.replace(/^\/+|\/+$/g, '');

  const params = new URLSearchParams(loc.search);
  const route = params.get('route') || null;
  const queryView = params.get('view');
  const resolved = resolveSectionToken(seg || queryView);
  return { target: { section: resolved.section, route }, anchor: resolved.anchor };
}

