/** API base. Default '/api' (same-origin, dev proxy + same-origin prod).
 *  T150: a cross-origin deployment (static frontend on Pages, API on box #2)
 *  builds with VITE_API_BASE=https://<api-domain>/api so the frozen Pages
 *  demo and the live app share one codebase — only the build differs. Must
 *  end WITHOUT a trailing slash. */
const BASE = (import.meta.env.VITE_API_BASE ?? '/api').replace(/\/$/, '');
export const API_BASE = BASE;

// Cache for GET requests with 30s TTL
interface CacheEntry<T> {
  promise: Promise<T>;
  timestamp: number;
}

const getCache = new Map<string, CacheEntry<any>>;
const CACHE_TTL = 30000; // 30 seconds

function cacheGet<T>(key: string, fetchFn: () => Promise<T>): Promise<T> {
  const now = Date.now();
  const entry = getCache.get(key);
  
  // Return cached promise if it exists and is still valid
  if (entry && (now - entry.timestamp) < CACHE_TTL) {
    return entry.promise;
  }
  
  // Create new promise and cache it; evict on rejection so a failed GET
  // doesn't stay poisoned for the full TTL — the next call retries the network.
  const promise: Promise<T> = fetchFn().catch((err) => {
    const e = getCache.get(key);
    if (e && e.promise === promise) getCache.delete(key);
    throw err;
  });
  getCache.set(key, { promise, timestamp: now });
  return promise;
}

// Cleanup expired cache entries periodically
function cleanupCache() {
  const now = Date.now();
  for (const [key, entry] of getCache.entries()) {
    if (now - entry.timestamp >= CACHE_TTL) {
      getCache.delete(key);
    }
  }
}

// Cleanup every minute
setInterval(cleanupCache, 60000);

export async function handle<T>(resp: Response): Promise<T> {
  if (!resp.ok) {
    const text = await resp.text().catch(() => '');
    let detail: string;

    // FastAPI's own errors (e.g. the clear 404/409 messages, unhandled
    // exceptions raised via ``internal_error``) always carry JSON `detail`.
    // Use it verbatim when present.
    let parsed: unknown = null;
    try {
      parsed = JSON.parse(text);
    } catch {
      parsed = null;
    }
    const body = parsed as { detail?: unknown } | null;
    if (body && typeof body.detail === 'string') {
      detail = body.detail;
    } else if (resp.status === 500) {
      // Two very different things look like a 500 here, so don't collapse the
      // diagnosis into one message:
      //  * empty body  -> Vite's dev proxy couldn't reach the FastAPI backend
      //    at all (backend genuinely down).
      //  * non-empty   -> the backend is up but a request crashed (FastAPI's
      //    default handler returns plain-text "Internal Server Error"; from
      //    `internal_error` it returns JSON detail, handled above). Conflating
      //    these told users "is the API server running?" when the backend was
      //    fine and the bug was a crashed endpoint.
      detail = text.trim()
        ? 'Server error (HTTP 500) — the backend is up but hit an error on this request. Check the server log.'
        : 'Backend unreachable — is the API server running?';
    } else {
      detail = `HTTP ${resp.status}`;
    }
    throw new Error(detail);
  }
  return resp.json() as Promise<T>;
}

