import { Info } from 'lucide-react';
import { useEffect, useState } from 'react';
import { DEMO_MODE } from '../lib/static-patch';

/**
 * Demo-mode banner. Rendered at the top of the app when the frontend is
 * serving frozen API snapshots (GitHub Pages / static demo) instead of a
 * live backend, so no one mistakes the demo for the live system.
 *
 * The vintage line comes from api-snapshot/manifest.json, stamped by
 * scripts/snapshot-api.mjs at capture time.
 */
type ManifestProvenance = {
  showcase_commit?: string | null;
  showcase_url?: string;
  dataset_doi?: string;
  dataset_url?: string;
};

export default function DemoBanner() {
  const [vintage, setVintage] = useState<string | null>(null);
  const [provenance, setProvenance] = useState<ManifestProvenance | null>(null);

  useEffect(() => {
    if (!DEMO_MODE) return;
    const base = (import.meta.env.BASE_URL ?? '/').replace(/\/$/, '');
    fetch(`${base}/api-snapshot/manifest.json`)
      .then((r) => (r.ok ? r.json() : null))
      .then((m) => {
        setVintage(m?.vintage ?? null);
        setProvenance(m?.provenance ?? null);
      })
      .catch(() => {
        setVintage(null);
        setProvenance(null);
      });
  }, []);

  if (!DEMO_MODE) return null;

  return (
    <div className="flex flex-wrap items-center gap-2 border-b border-bottleneck/40 bg-bottleneck/10 px-4 py-1.5 text-xs text-text-secondary">
      <Info className="h-3.5 w-3.5 shrink-0 text-bottleneck" />
      <span>
        <strong className="text-text-primary">Demo mode</strong> — read-only replay of frozen
        snapshots{vintage ? ` (${vintage})` : ''}. Optimizer results are pre-computed; travel-time
        and equity calculators need the live system.
      </span>
      {provenance?.showcase_commit && (
        <a
          href={`${provenance.showcase_url ?? 'https://github.com/Tapl1338/miway-findings'}/commit/${provenance.showcase_commit}`}
          className="shrink-0 underline hover:text-text-primary"
          title="The exact commit that captured the snapshots on screen"
        >
          demo @ {provenance.showcase_commit}
        </a>
      )}
      {provenance?.dataset_url && (
        <a
          href={provenance.dataset_url}
          className="shrink-0 underline hover:text-text-primary"
          title="The published, DOI-pinned dataset behind the findings views"
        >
          dataset DOI {provenance.dataset_doi}
        </a>
      )}
      <a
        href="https://github.com/Tapl1338/miway-findings"
        className="ml-auto shrink-0 underline hover:text-text-primary"
      >
        How this data is measured
      </a>
    </div>
  );
}
